DO $$BEGIN
 BEGIN
 INSERT INTO lesson_sessions(id,class_id,ordinal,during,state) VALUES(pg_temp.tid('batch-ok'),pg_temp.tid('class'),20,tstzrange('2030-04-01T11:00Z','2030-04-01T12:30Z','[)'),'SCHEDULED');
 INSERT INTO lesson_sessions(id,class_id,ordinal,during,state) VALUES(pg_temp.tid('batch-bad'),pg_temp.tid('class'),21,tstzrange('2030-01-07T11:00Z','2030-01-07T12:30Z','[)'),'SCHEDULED');
 RAISE EXCEPTION 'expected conflict'; EXCEPTION WHEN exclusion_violation THEN NULL; END;
 PERFORM pg_temp.assert_true(NOT EXISTS(SELECT 1 FROM lesson_sessions WHERE id=pg_temp.tid('batch-ok')),'batch rollback'); END $$;
